PREFIX proveedores: <https://w3id.org/rastro/proveedores#>
SELECT (SUM(?amt) AS ?total) WHERE {
  SELECT DISTINCT ?c ?amt WHERE {
    ?c a proveedores:Contract ; proveedores:supplier ?s ; proveedores:amount ?amt .
    ?s proveedores:group ?g . ?g proveedores:name ?gn .
    FILTER(CONTAINS(UCASE(?gn), "LEIDOS"))
  }
}
